        let tracked cb_combiner = cb_combiner.get();
        let replicated_data_structure = ReplicatedDataStructure {
            data,
            replica: Tracked(ghost_replica),
            combiner: Tracked(combiner),
            cb_combiner: Tracked(cb_combiner),
        };
